// Package pricing provides static cloud list-price tables for cost math.
// Prices are ON-DEMAND LIST prices — reports must label them as such and
// point users at --discount for RI/Savings-Plans-adjusted numbers.
//
// The tables live in tables_gen.go, regenerated by scripts/update-pricing.py
// from real cloud sources (AWS ec2.shop + Price List API, the Azure Retail
// Prices API, and a verified GCP Compute Engine rate table) and stamped with a
// fetch date (see AsOf). This package is OSS-side and must NOT import
// internal/report.
package pricing

import (
	"sort"
	"strings"

	"github.com/Shoalcheck/shoalcheck-scan/internal/types"
)

// HoursPerMonth is the convention used to convert hourly rates to monthly.
// 730 = 8760h / 12 — the standard cloud billing month.
const HoursPerMonth = 730

// AsOf returns the date stamp of the embedded price table (YYYY-MM).
//
// The full fetch date is YYYY-MM-DD; callers get the YYYY-MM month form, which
// is the granularity worth surfacing in a report ("prices as of 2026-06").
func AsOf() string {
	// asOf is "YYYY-MM-DD"; return the leading "YYYY-MM".
	return asOf[:7]
}

// normalizeProvider maps the various provider spellings a caller might hold
// onto the three keys the tables use: "aws", "azure", "gcp". The Kubernetes
// provider tags ("eks"/"aks"/"gke") and the raw cloud names both normalize
// here, so callers never have to remember which form the table wants. An
// unrecognized value passes through lowercased and simply won't match a table.
func normalizeProvider(provider string) string {
	switch strings.ToLower(provider) {
	case "aws", "eks":
		return "aws"
	case "azure", "aks":
		return "azure"
	case "gcp", "gke", "google":
		return "gcp"
	default:
		return strings.ToLower(provider)
	}
}

// RegionCovered reports whether the node-pricing table has ANY instance prices
// for a provider+region pair. provider accepts the cloud name ("aws"/"azure"/
// "gcp") or the Kubernetes tag ("eks"/"aks"/"gke"); both normalize internally.
//
// This is the pre-flight guard against the report's single biggest credibility
// risk: the tables cover AWS densely but only a handful of Azure/GCP regions, so
// an AKS/GKE cluster in (say) francecentral has NO node price and silently sums
// its compute to $0. A false here means "do not present a cost headline as if it
// were priced" — the caller suppresses the headline and warns instead of showing
// a fabricated near-zero number.
func RegionCovered(provider, region string) bool {
	regions, ok := nodeHourlyUSD[normalizeProvider(provider)]
	if !ok {
		return false
	}
	byType, ok := regions[region]
	return ok && len(byType) > 0
}

// CoveredRegions returns the sorted list of regions the node-pricing table
// covers for a provider (cloud name or k8s tag). It is the operator-facing seam
// for "add the region to internal/pricing or footnote it" — the warning path can
// list what IS covered so the gap is actionable. An unknown provider yields nil.
func CoveredRegions(provider string) []string {
	regions, ok := nodeHourlyUSD[normalizeProvider(provider)]
	if !ok {
		return nil
	}
	out := make([]string, 0, len(regions))
	for r, byType := range regions {
		if len(byType) > 0 {
			out = append(out, r)
		}
	}
	sort.Strings(out)
	return out
}

// NodeMonthlyUSD returns the on-demand monthly price for an instance type in a
// region for the given cloud provider. provider accepts either the cloud name
// ("aws"/"azure"/"gcp") or the Kubernetes provider tag ("eks"/"aks"/"gke");
// both normalize internally. ok=false when the provider, region, or type is
// unknown — callers must render "unknown" honestly, never 0 as if it were a
// price.
//
// The capacity argument carries the node's purchase basis (spot/on-demand/
// unknown) so this signature is the forward-compatible seam for a future spot
// price table. TODAY THE VALUE DOES NOT CHANGE WITH capacity: there is no spot
// table and the realized spot rate is unreadable from node labels, so a spot
// pool gets the SAME on-demand list number, treated as an UPPER BOUND (a
// "ceiling"), with NO fabricated multiplier. Pricing spot "differently" is true
// only in the provenance sense (the caller stamps CostSourceSpotCeiling) — the
// dollar figure is unchanged. A skimming reader should not expect a lower spot
// number here.
func NodeMonthlyUSD(provider, region, instanceType string, capacity types.CapacityType) (usd float64, ok bool) {
	regions, ok := nodeHourlyUSD[normalizeProvider(provider)]
	if !ok {
		return 0, false
	}
	byType, ok := regions[region]
	if !ok {
		return 0, false
	}
	hourly, ok := byType[instanceType]
	if !ok {
		return 0, false
	}
	// capacity is intentionally NOT used to scale the number today (see doc): a
	// spot pool returns its on-demand list price as a ceiling, never a fabricated
	// lower spot rate. When a real spot table or Layer 2 billing lands, the spot
	// branch changes here — and only here.
	_ = capacity
	return hourly * HoursPerMonth, true
}

// LBMonthlyUSD returns the monthly BASE price of one cloud load balancer for a
// provider+region (hourly * 730). This is the FIXED per-LB charge only — it
// EXCLUDES capacity/rule/data-processing usage (AWS LCU/NLCU, Azure rule &
// data overage, GCP per-rule & data), which is traffic-dependent and cannot be
// priced from a static table. ok=false for an unknown provider/region.
//
// AWS prices are per-region (Network Load Balancer base). Azure (Standard LB)
// and GCP (forwarding rule) use a flat global base, stored under the "*" key,
// so any region resolves to the same base rate.
func LBMonthlyUSD(provider, region string) (float64, bool) {
	byRegion, ok := lbHourlyUSD[normalizeProvider(provider)]
	if !ok {
		return 0, false
	}
	hourly, ok := byRegion[region]
	if !ok {
		// Flat-rate providers (Azure/GCP) store a single "*" entry.
		hourly, ok = byRegion["*"]
		if !ok {
			return 0, false
		}
	}
	return hourly * HoursPerMonth, true
}

// ControlPlaneMonthlyUSD returns the monthly managed control-plane charge per
// cluster for a provider (hourly * 730). It is 0 for an unknown provider and
// for providers with no per-cluster fee (e.g. AKS free tier). Use ok-style
// callers' own provider check to decide whether to add it; a 0 here means
// "no modelled fee", which is the honest default.
//
//	aws (EKS):   $0.10/cluster-hour = $73/mo.
//	azure (AKS): $0 — free tier default (Standard uptime-SLA tier is opt-in).
//	gcp (GKE):   $0.10/cluster-hour = $73/mo (after the one free zonal cluster).
func ControlPlaneMonthlyUSD(provider string) float64 {
	return controlPlaneHourlyUSD[normalizeProvider(provider)] * HoursPerMonth
}

// EBSGp3MonthlyUSDPerGB returns the AWS gp3 storage price per GB for one month
// in a region. Multiply by provisioned GiB for a volume's monthly cost.
// ok=false for unknown regions. (gp3's free 3000 IOPS / 125 MB/s baseline is
// assumed; any provisioned IOPS/throughput above baseline is billed separately
// and is not covered here.) AWS-only — Azure/GCP managed-disk pricing is not
// modelled.
func EBSGp3MonthlyUSDPerGB(region string) (float64, bool) {
	byType, ok := ebsGBMonthUSD[region]
	if !ok {
		return 0, false
	}
	usd, ok := byType["gp3"]
	return usd, ok
}

// ExtendedSupportHourly returns the per-cluster HOURLY SURCHARGE a provider bills for running a
// Kubernetes version past ordinary support, and ok=false where no free published rate exists.
//
// IT IS THE SURCHARGE, NOT THE TOTAL. What an upgrade stops is this amount; the ordinary control
// plane is billed either way. Reporting the total as recoverable would say a cluster becomes free.
//
// ok=false is the honest state for GKE: Google publishes no free structured price endpoint, so the
// version finding is structural there rather than priced. It is never a zero.
func ExtendedSupportHourly(provider string) (float64, bool) {
	usd, ok := extendedSupportHourlyUSD[normalizeProvider(provider)]
	if !ok || usd <= 0 {
		return 0, false
	}
	return usd, true
}

// StorageMonthlyPerGB returns the per-GB-month LIST storage price for a
// provider+region+diskType. provider accepts cloud name or k8s tag (normalized).
// ok=false for an unknown provider, region, or disk type — an unmapped
// StorageClass must be recorded (UnpricedStorageClasses), NEVER priced as the
// cheapest tier. GCP storage is not modelled and always returns ok=false.
func StorageMonthlyPerGB(provider, region, diskType string) (float64, bool) {
	// AWS EBS COMES FROM THE GENERATED TABLE, NOT A SECOND HAND-KEPT COPY.
	//
	// storage_egress_gen.go carried its own "aws" block holding the same gp3 numbers as
	// tables_gen.go's. They agreed on the day this was found and nothing kept them agreeing: the
	// generator refreshes one and has never written the other. Two literals for one price is a drift
	// with a start date, so the generated one is now the only one, and gp2 arrives with it.
	if normalizeProvider(provider) == "aws" {
		byType, ok := ebsGBMonthUSD[region]
		if !ok {
			return 0, false
		}
		usd, ok := byType[diskType]
		return usd, ok
	}
	regions, ok := storageGBMonthUSD[normalizeProvider(provider)]
	if !ok {
		return 0, false
	}
	byType, ok := regions[region]
	if !ok {
		return 0, false
	}
	usd, ok := byType[diskType]
	if !ok {
		return 0, false
	}
	return usd, true
}

// EgressPerGB returns the per-GB internet data-transfer-out LIST price for a
// provider+region (first tier; inter-AZ/region transfer not modelled).
// ok=false for an unknown provider or region.
func EgressPerGB(provider, region string) (float64, bool) {
	byRegion, ok := egressGBUSD[normalizeProvider(provider)]
	if !ok {
		return 0, false
	}
	usd, ok := byRegion[region]
	return usd, ok
}

// NLBMonthlyUSD is a backward-compatible AWS-only shim for LBMonthlyUSD("aws",
// region). Prefer LBMonthlyUSD for new code.
func NLBMonthlyUSD(region string) (float64, bool) {
	return LBMonthlyUSD("aws", region)
}

// EKSControlPlaneMonthlyUSD is a backward-compatible shim for
// ControlPlaneMonthlyUSD("aws"). Prefer ControlPlaneMonthlyUSD for new code.
func EKSControlPlaneMonthlyUSD() float64 {
	return ControlPlaneMonthlyUSD("aws")
}

// NodePriceCount is how many (provider, region, instance type) node rates the bundled table holds.
//
// IT EXISTS SO A DOCUMENT CAN QUOTE IT. The register's masthead says "85,732 prices in the table" and
// nothing held that number: it was re-derived by hand each time somebody noticed, which is the mechanism
// behind twenty-two of the defects in docs/DECISIONS.md. internal/gatecheck reads this and holds every live
// document against it.
func NodePriceCount() int {
	n := 0
	for _, byRegion := range nodeHourlyUSD {
		for _, byType := range byRegion {
			n += len(byType)
		}
	}
	return n
}
